from exgen import Q, C
def H(n): return dict(hint=(f"Lesson {n}.", f"Lição {n}."))
def qz(n, d, pe, pp, *cs): return Q(None, None, "quiz", d, (pe, pp), choices=[C(*c) for c in cs], **H(n))
